// La pièce jointe Fastmag (CSV) passe en base64 telle quelle : le portail la décode (windows-1252).
const sortie = [];
for (const item of $input.all()) {
  const cle = Object.keys(item.binary || {}).find(k => /\.(csv|xls|txt|tsv)$/i.test(item.binary[k].fileName || '')) || Object.keys(item.binary || {})[0];
  if (!cle) continue;
  const octets = await this.helpers.getBinaryDataBuffer($input.all().indexOf(item), cle);
  sortie.push({ json: {
    action: 'stock_fastmag',
    fichier: `${item.json.subject || 'Stock Theorique'} — ${item.binary[cle].fileName || 'piece jointe'}`,
    fichier_base64: octets.toString('base64'),
    plafonner: true,
    simuler: false
  } });
}
if (!sortie.length) throw new Error('aucune pièce jointe dans ce mail');
return sortie;

// Compte rendu lisible (à envoyer par mail, Slack, WhatsApp… au choix).
const r = $input.first().json;
const p = r.plafonnement || {};
const lignes = (p.details || []).slice(0, 40).map(d => `${d.magasin} ${d.reference} ${d.taille} : ${d.avant} → ${d.apres}`).join('\n');
return [{ json: {
  sujet: `FKB2B stock : ${p.lignes} ligne(s) B2B abaissée(s), ${p.pieces_retirees} pièces`,
  texte: `État Fastmag chargé : ${r.lignes} lignes (${(r.magasins || []).join(', ')}).\nPlafonnement : ${p.lignes} lignes, ${p.pieces_retirees} pièces retirées ${JSON.stringify(p.par_magasin)}.\n\n${lignes}${p.lignes > 40 ? '\n…' : ''}`
} }];
